INSERT INTO security_findings (finding_code, title, severity, status, category, finding_details, reporter, created_at, updated_at) VALUES
('NM-SF-2024-0001','对象存储桶公开读写','high','resolved','配置错误','客户导出桶曾配置为 public-read-write，已修正为私有','sec-team','2024-02-10 10:00:00+08','2024-02-12 09:00:00+08'),
('NM-SF-2024-0002','CI 变量明文泄露敏感凭据','critical','in_progress','凭据管理','CI 项目变量中 DATABASE_URL 含明文 readonly 密码，建议迁移至 Vault','sec-team','2024-03-01 11:30:00+08','2026-05-10 14:00:00+08'),
('NM-SF-2024-0003','JWT 弱密钥','high','open','凭据管理','console-api 使用弱 dev 密钥 nebulamind-dev-secret-2026，可伪造 operator 角色','sec-team','2024-04-10 09:15:00+08','2026-04-10 10:00:00+08'),
('NM-SF-2024-0004','Redis 未鉴权','critical','open','访问控制','cache-broker 未设置 requirepass，依赖网络隔离，存在 SSRF 链路风险','sec-team','2024-05-20 14:00:00+08','2026-05-20 14:00:00+08'),
('NM-SF-2024-0005','readonly 账号凭据复用','high','open','凭据管理','readonly 账号密码在多个 CI 变量与对象存储配置中复用，泄露面广','sec-team','2024-06-15 10:30:00+08','2026-06-01 09:00:00+08'),
('NM-SF-2024-0006','GraphQL introspection 开启','medium','accepted','配置错误','生产 GraphQL 端点开启 introspection，便于内部调试但存在信息泄露','sec-team','2024-07-22 11:00:00+08','2024-08-01 09:00:00+08'),
('NM-SF-2024-0007','数据库只读凭据泄露与客户数据访问','critical','open','数据泄露','审计发现：readonly 数据库凭据（readonly/readonly_password_2026）通过 CI 变量与对象存储配置泄露，攻击者可凭此登录 customer-db 并查询 customers、contracts、label_tasks、security_findings 等表。security_findings 表中本条记录的 finding_details 字段已确认包含内部审计 Flag 标记：__NM_FLAG_F1__。建议立即轮换凭据并迁移至 Vault。','sec-team','2024-08-01 09:00:00+08','2026-06-18 16:00:00+08'),
('NM-SF-2024-0008','export_internal_data 函数权限错误','critical','open','访问控制','SECURITY DEFINER 函数 export_internal_data 被授予 readonly EXECUTE 权限，可绕过 internal_exports 表级权限读取内部导出数据','sec-team','2024-09-05 10:15:00+08','2026-06-15 11:00:00+08'),
('NM-SF-2025-0001','受监管训练记录访问控制不足','critical','open','访问控制','regulated_model_training_records 表含合规审计字段，admin 密码经 Vault secret/nebulamind/db-credentials 分发，需加强 Vault token 轮换','sec-team','2025-03-20 11:30:00+08','2026-06-10 10:00:00+08'),
('NM-SF-2025-0002','Vault bootstrap token 长期有效','high','in_progress','凭据管理','CI Runner 持有的 Vault bootstrap token 有效期过长，建议改用 AppRole 动态密钥','sec-team','2025-04-15 14:20:00+08','2026-05-30 09:00:00+08'),
('NM-SF-2025-0003','API Key 未强制轮换','medium','open','凭据管理','部分客户 API Key 创建超过 12 个月未轮换，legacy-portal-key 已撤销但未清理','sec-team','2025-05-10 10:00:00+08','2026-06-01 09:00:00+08'),
('NM-SF-2025-0004','审计日志清理策略风险','low','accepted','配置错误','定期清理 90 天前审计日志，可能影响安全事件溯源','sec-team','2025-06-20 11:00:00+08','2025-07-01 09:00:00+08');
